import{_ as a,o as t,c as h,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"04 — Media Package, Campaign và Content Request","description":"","frontmatter":{},"headers":[],"relativePath":"ba/04-media-package-campaign.md","filePath":"ba/04-media-package-campaign.md"}'),e={name:"ba/04-media-package-campaign.md"};function c(g,n,o,r,l,u){return t(),h("div",null,[...n[0]||(n[0]=[i('<h1 id="_04-—-media-package-campaign-va-content-request" tabindex="-1">04 — Media Package, Campaign và Content Request <a class="header-anchor" href="#_04-—-media-package-campaign-va-content-request" aria-label="Permalink to &quot;04 — Media Package, Campaign và Content Request&quot;">​</a></h1><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a></p><p>&gt; <strong>BA đã chốt 2026-11-05</strong> theo <a href="./../feature/media-package-campaign/guest-sharing-manager-led/spec.html">spec Guest sharing và Manager-led</a>. Đợt này chỉ cập nhật đặc tả. Flow Client chọn/đàm phán/duyệt Package và duyệt Campaign hai phía được thay thế trong phạm vi Package/Campaign. Quyền duyệt kết quả Task/bài đăng và Content Request theo spec riêng.</p><h2 id="_1-hanh-trinh-hien-hanh" tabindex="-1">1. Hành trình hiện hành <a class="header-anchor" href="#_1-hanh-trinh-hien-hanh" aria-label="Permalink to &quot;1. Hành trình hiện hành&quot;">​</a></h2><ol><li>Owner tạo Media Package trong danh mục Agency.</li><li>Hệ thống hỗ trợ Owner xuất ảnh/PDF hoặc link guest để quảng bá, gửi cho khách xem.</li><li>Khách xem gói được chia sẻ trước khi có tài khoản hoặc membership workspace. Link luôn hiển thị bản mới nhất đã lưu của đúng gói Agency hoặc Custom Package workspace được chia sẻ.</li><li>Owner tạo workspace và gán Manager. Chưa bắt buộc có Client.</li><li>Manager chốt gói với Client bên ngoài hệ thống.</li><li>Manager chọn gói Agency để tùy chỉnh hoặc tạo mới trong workspace, ghi nhận đúng thỏa thuận.</li><li>Lưu gói workspace hợp lệ tự tạo một Campaign DRAFT và task lớn theo gói. Lưu lại/retry không sinh trùng.</li><li>Manager mời Client vào workspace để xem gói đã ghi nhận, xem kế hoạch và comment góp ý cả khi Campaign còn DRAFT.</li><li>Manager hoàn thiện kế hoạch và chủ động triển khai khi đủ điều kiện. Bỏ bước duyệt Campaign hai phía.</li><li>Client theo dõi và góp ý. Những thao tác duyệt kết quả Task/nội dung thuộc quy trình riêng.</li></ol><p>Một workspace tiếp tục có một Campaign. Manager được sửa gói trước triển khai và đồng bộ kế hoạch/task, giữ thông tin đã nhập ở hạng mục còn hiệu lực. Khi triển khai phải cố định bản gói/kế hoạch dùng cho lượt đó, khóa sau triển khai. Góp ý của Client không trở thành gate duyệt.</p><h2 id="_2-media-package-—-fr-3-5-1-đen-3-5-4" tabindex="-1">2. Media Package — FR 3.5.1 đến 3.5.4 <a class="header-anchor" href="#_2-media-package-—-fr-3-5-1-đen-3-5-4" aria-label="Permalink to &quot;2. Media Package — FR 3.5.1 đến 3.5.4&quot;">​</a></h2><h3 id="_3-5-1-—-tao-goi" tabindex="-1">3.5.1 — Tạo gói <a class="header-anchor" href="#_3-5-1-—-tao-goi" aria-label="Permalink to &quot;3.5.1 — Tạo gói&quot;">​</a></h3><p>Owner quản lý danh mục Agency để quảng bá độc lập với workspace. Manager tạo gói thực hiện trong workspace từ mẫu hoặc nhập mới theo thỏa thuận bên ngoài, không cần thêm lượt duyệt Owner/Client.</p><p>Gói workspace giữ nội dung riêng và nguồn tham khảo khi có. Chỉnh gói quảng bá không tự sửa điều khoản gói workspace hoặc Campaign/task. Ngân sách và thời lượng tùy chọn. Giữ tổng sản lượng, đơn vị, dịch vụ và phạm vi bàn giao hiện hành, theo <a href="./../feature/package-driven-campaign-tasks/spec.html">spec package-driven</a>.</p><h3 id="_3-5-2-—-guest-view-va-chia-se" tabindex="-1">3.5.2 — Guest view và chia sẻ <a class="header-anchor" href="#_3-5-2-—-guest-view-va-chia-se" aria-label="Permalink to &quot;3.5.2 — Guest view và chia sẻ&quot;">​</a></h3><p>Owner xuất gói Agency đã lưu thành ảnh/PDF hoặc chia sẻ link. Manager phụ trách/Owner có quyền quản lý cũng chia sẻ được Custom Package workspace qua ba hình thức này để trao đổi với Client. Guest xem nội dung gói mà không cần đăng nhập. Link đọc bản mới nhất của đúng gói, ảnh/PDF là bản tại thời điểm xuất và có ngày xuất để đối chiếu. Cơ chế bảo mật nâng cao sẽ được bàn với team sau.</p><p>Link chỉ hiển thị nội dung và điều khoản của gói được chia sẻ; không trả Client Profile, quyền truy cập workspace, bình luận hoặc lịch sử đàm phán/duyệt. Có link không tự tạo workspace, đơn hàng, xác nhận mua hoặc membership.</p><h3 id="_3-5-3-—-ghi-nhan-va-đieu-chinh-thoa-thuan" tabindex="-1">3.5.3 — Ghi nhận và điều chỉnh thỏa thuận <a class="header-anchor" href="#_3-5-3-—-ghi-nhan-va-đieu-chinh-thoa-thuan" aria-label="Permalink to &quot;3.5.3 — Ghi nhận và điều chỉnh thỏa thuận&quot;">​</a></h3><p>Manager thực hiện trao đổi/chốt với Client bên ngoài, rồi lưu điều khoản gói trong workspace. Client vào workspace sau để xem thông tin đã ghi nhận. Bỏ hành trình request-change/counter-offer của Client trên hệ thống.</p><p>Trước triển khai, chỉnh gói phải đồng bộ Campaign/task, bảo toàn dữ liệu đã nhập và xử lý tác động giảm/đổi hạng mục có xác nhận cần thiết. Gói/kế hoạch đã triển khai được khóa, phát sinh mới theo quy trình bổ sung hiện hành.</p><h3 id="_3-5-4-—-thay-buoc-duyet-package" tabindex="-1">3.5.4 — Thay bước duyệt Package <a class="header-anchor" href="#_3-5-4-—-thay-buoc-duyet-package" aria-label="Permalink to &quot;3.5.4 — Thay bước duyệt Package&quot;">​</a></h3><p>Không yêu cầu Client chọn hay duyệt gói. Lưu gói workspace hợp lệ là điểm tự tạo Campaign DRAFT và task, không có bước xác nhận gói riêng sau lưu. Các redirect, checklist và điều kiện chờ Client duyệt Package của flow cũ cần được thay thế khi triển khai.</p><h2 id="_3-media-campaign-—-fr-3-5-5-đen-3-5-6" tabindex="-1">3. Media Campaign — FR 3.5.5 đến 3.5.6 <a class="header-anchor" href="#_3-media-campaign-—-fr-3-5-5-đen-3-5-6" aria-label="Permalink to &quot;3. Media Campaign — FR 3.5.5 đến 3.5.6&quot;">​</a></h2><h3 id="_3-5-5-—-campaign-draft-tu-goi" tabindex="-1">3.5.5 — Campaign DRAFT từ gói <a class="header-anchor" href="#_3-5-5-—-campaign-draft-tu-goi" aria-label="Permalink to &quot;3.5.5 — Campaign DRAFT từ gói&quot;">​</a></h3><p>Campaign là kế hoạch thực hiện gói đã ghi nhận trong workspace. Backend tự tạo Campaign DRAFT/task khi Manager lưu gói hợp lệ. Manager tiếp tục bổ sung strategy, timeline, brief/deadline và các thông tin thực hiện còn thiếu. Task/subtask theo contract riêng, thành viên bắt đầu khi Campaign IN_PROGRESS.</p><h3 id="_3-5-6-—-client-gop-y-manager-trien-khai" tabindex="-1">3.5.6 — Client góp ý, Manager triển khai <a class="header-anchor" href="#_3-5-6-—-client-gop-y-manager-trien-khai" aria-label="Permalink to &quot;3.5.6 — Client góp ý, Manager triển khai&quot;">​</a></h3><p>Client đã tham gia workspace xem/comment góp ý cả bản nháp. Comment lưu người/thời điểm/ngữ cảnh đang xem, không sửa kế hoạch hoặc chuyển trạng thái. Manager quyết định điều chỉnh kế hoạch theo trạng thái cho phép.</p><p>Manager triển khai khi kế hoạch/task đủ thông tin và khớp gói. Không yêu cầu trạng thái APPROVED hay timestamp duyệt Campaign hai phía. Lượt triển khai phải cố định bản được dùng, giữ task identity, chống trùng và hỗ trợ retry. Thành công chuyển Campaign IN_PROGRESS, sau đó gói/phạm vi kế hoạch được khóa.</p><p>Vòng đời nghiệp vụ đích là DRAFT → IN_PROGRESS → COMPLETED. Điều kiện hoàn thành tiếp tục theo <a href="./../feature/media-package-campaign/campaign-closure/spec.html">Campaign closure</a> và <a href="./../feature/package-driven-campaign-tasks/spec.html">package-driven task</a>. Duyệt kết quả Task/bài đăng không được thay bằng comment Campaign.</p><h3 id="lich-su-va-pham-vi-thiet-ke" tabindex="-1">Lịch sử và phạm vi thiết kế <a class="header-anchor" href="#lich-su-va-pham-vi-thiet-ke" aria-label="Permalink to &quot;Lịch sử và phạm vi thiết kế&quot;">​</a></h3><p>Giữ lịch sử đàm phán, approval và dữ liệu cũ để truy vết. Mapping dữ liệu legacy, endpoint, schema và quyền truy cập sẽ chốt trong plan triển khai. Spec này không tạo migration, không xác nhận implementation và không mở thêm Campaign Addendum hoặc checkout/thanh toán.</p><p>Các phần Content Request bên dưới giữ phạm vi hiện hành. Những ghi chú lịch sử không liên quan Package/Campaign phải được đọc cùng spec riêng mới nhất đã dẫn.</p><h2 id="_4-content-request-—-kenh-bo-sung-rieng-fr-3-5-7-–-3-5-10" tabindex="-1">4. Content Request — kênh bổ sung riêng (FR 3.5.7 – 3.5.10) <a class="header-anchor" href="#_4-content-request-—-kenh-bo-sung-rieng-fr-3-5-7-–-3-5-10" aria-label="Permalink to &quot;4. Content Request — kênh bổ sung riêng (FR 3.5.7 – 3.5.10)&quot;">​</a></h2><p>&gt; <strong>Quyết định người dùng 2026-10-14 (cần đồng bộ với team):</strong> chỉ Client thuộc Workspace có Campaign IN_PROGRESS và deployment SUCCEEDED được tạo Request. Client sửa title/description/type/dueDate hoặc hủy khi PENDING. Deadline từ ngày hiện tại, không trước ngày bắt đầu và không sau ngày kết thúc Campaign, theo timezone Workspace. Manager chủ động tiếp nhận để chuyển IN_PROGRESS và khóa sửa/hủy của Client; sau đó ACCEPTED hoặc DENIED. Hủy là CANCELLED, không xóa. Request được chấp nhận sinh đúng một Task BACKLOG, campaignId=null. Khi Manager đánh dấu Campaign COMPLETED, chặn tạo mới và tự hủy PENDING có lịch sử; IN_PROGRESS tiếp tục xử lý. Hết ngày kế hoạch không tự hoàn thành Campaign. Quy tắc này thay thế quyết định 2026-10-13 giữ PENDING sau hoàn thành.</p><p>Đây là 1 luồng <strong>bổ sung, độc lập</strong> với luồng Package/Campaign chính — cho phép Client đề xuất thêm 1 bài đăng cụ thể ngoài kế hoạch Campaign đã duyệt.</p><h3 id="_3-5-7-—-create-content-request" tabindex="-1">3.5.7 — Create Content Request <a class="header-anchor" href="#_3-5-7-—-create-content-request" aria-label="Permalink to &quot;3.5.7 — Create Content Request&quot;">​</a></h3><ul><li>Client tạo được bài content mới, chờ Manager coi và quyết định đồng ý làm hay không.</li><li>Nếu đồng ý → chuyển trạng thái <code>accepted</code> để phân chia task cho role khác thực hiện.</li><li><strong>[CONFIRMED 2026-09-15]</strong> Nếu Manager từ chối → <code>denied</code> là trạng thái <strong>cuối (terminal)</strong>, khác với Task reject. Client không sửa lại được request đã denied — phải tạo Content Request mới hoàn toàn nếu muốn đề xuất lại.</li><li>Ghi chú thêm: cần <strong>note lại</strong> để sau này tính vào công việc bổ sung (có thể liên quan đến billing/KPI ngoài phạm vi Package gốc).</li><li><strong>[CONFIRMED 2026-09-14]</strong> Role list trong CSV ghi cả OWNER/MANAGER/CLIENT, nhưng thực tế hành động <strong>Create chỉ do CLIENT thực hiện</strong> — Owner/Manager có mặt trong role list vì họ có quyền TRUY CẬP xem màn hình này (để duyệt), không phải vì họ tự tạo request cho mình.</li></ul><h3 id="_3-5-8-—-track-request-status" tabindex="-1">3.5.8 — Track Request Status <a class="header-anchor" href="#_3-5-8-—-track-request-status" aria-label="Permalink to &quot;3.5.8 — Track Request Status&quot;">​</a></h3><ul><li>Manager điều chỉnh status của yêu cầu do Client đưa lên.</li><li>Luồng trạng thái: <code>pending → in progress → accept</code> (chuyển công việc vào backlog) hoặc <code>denied</code>.</li><li>4 trạng thái (pending / in progress / accept / denied) <strong>do Agency setting quyết định</strong> — Client hoàn toàn không có quyền tự set trạng thái.</li><li>Role: MANAGER.</li><li><strong>Ghi chú kèm theo trong nguồn</strong> (về Template Media Package, liên quan gián tiếp tới luồng): Template media package bao gồm số lượng bài, thời gian thực hiện, chất lượng nội dung... Team truyền thông thảo luận cụ thể hóa các bài viết → ra kế hoạch truyền thông (tiêu đề bài viết, nền tảng đăng tải...) → thảo luận với Client xem kế hoạch có ok không → ra hợp đồng chính thức để ký. Đây là mô tả luồng thực tế ngoài đời mà hệ thống đang số hóa lại qua Package→Campaign.</li></ul><h3 id="_3-5-9-—-update-request" tabindex="-1">3.5.9 — Update Request <a class="header-anchor" href="#_3-5-9-—-update-request" aria-label="Permalink to &quot;3.5.9 — Update Request&quot;">​</a></h3><ul><li>Client điều chỉnh nội dung content muốn thêm vào.</li><li><strong>Chỉ được làm khi đang ở trạng thái PENDING</strong>.</li><li>Role: CLIENT.</li></ul><h3 id="_3-5-10-—-cancel-request" tabindex="-1">3.5.10 — Cancel Request <a class="header-anchor" href="#_3-5-10-—-cancel-request" aria-label="Permalink to &quot;3.5.10 — Cancel Request&quot;">​</a></h3><ul><li>Khi Track Request Status đã đổi khỏi PENDING, Client <strong>không còn quyền xóa/hủy</strong> request nữa — hủy chỉ hợp lệ khi status vẫn là PENDING.</li><li>Role: CLIENT.</li></ul><h2 id="_5-lien-ket-voi-task-backlog" tabindex="-1">5. Liên kết với Task backlog <a class="header-anchor" href="#_5-lien-ket-voi-task-backlog" aria-label="Permalink to &quot;5. Liên kết với Task backlog&quot;">​</a></h2><p><strong>[CONFIRMED 2026-09-14]</strong> Khi Manager set trạng thái Content Request thành <code>accepted</code>, hệ thống <strong>tự động sinh 1 Task mới</strong> trong backlog của Workspace — task này sau đó chảy vào đúng quy trình Task chuẩn (Identify Task Detail → Assign → Approval Sequence...). Xem chi tiết đầy đủ tại <a href="./05-content-task-workflow.html">05-content-task-workflow.md</a>.</p><p>Ngoài nguồn từ Campaign (mục 3) và Content Request (mục 4), Manager còn được tự do thêm Task thủ công trực tiếp vào backlog bất cứ lúc nào (việc nội bộ, không cần qua Campaign hay Content Request) — xem file 05.</p>',42)])])}const k=a(e,[["render",c]]);export{p as __pageData,k as default};
